/* From Uiverse.io by gagan-gv - Tags: loading, loader, glow */
.__UIV_SCOPE__ .spinner {
 height: 50px;
 width: max-content;
 font-size: 18px;
 font-weight: 600;
 font-family: monospace;
 letter-spacing: 1em;
 color: #f5f5f5;
 filter: drop-shadow(0 0 10px);
 display: flex;
 justify-content: center;
 align-items: center;
}

.__UIV_SCOPE__ .spinner span {
 animation: loading6454 1.75s ease infinite;
}

.__UIV_SCOPE__ .spinner span:nth-child(2) {
 animation-delay: 0.25s;
}

.__UIV_SCOPE__ .spinner span:nth-child(3) {
 animation-delay: 0.5s;
}

.__UIV_SCOPE__ .spinner span:nth-child(4) {
 animation-delay: 0.75s;
}

.__UIV_SCOPE__ .spinner span:nth-child(5) {
 animation-delay: 1s;
}

.__UIV_SCOPE__ .spinner span:nth-child(6) {
 animation-delay: 1.25s;
}

.__UIV_SCOPE__ .spinner span:nth-child(7) {
 animation-delay: 1.5s;
}

@keyframes loading6454 {
 0%, 100% {
  transform: translateY(0);
 }

 50% {
  transform: translateY(-10px);
 }
}
